import { describe, expect, it } from "vitest";

import {
  mapGoal,
  mapLeaderboardEntry,
  mapProfile,
  mapStats,
  mapSubscription,
  mapTip,
} from "../src/SoroTipClient";
import type {
  RawCreatorProfile,
  RawLeaderboardEntry,
  RawProtocolStats,
  RawSubscription,
  RawTip,
  RawTipGoal,
} from "../src/SoroTipClient";
import fixtures from "./fixtures/contract-fixtures.json";

/**
 * These fixtures were generated by a real Rust test
 * (contracts/tip/src/test.rs::generate_sdk_fixtures in sorotip-contracts) —
 * every value below is something the actual contract computed and returned,
 * not an assumption about its wire shape made from this side. The amount,
 * fee, and timestamp values were deliberately chosen to exceed
 * Number.MAX_SAFE_INTEGER (2^53 - 1 = 9007199254740991), so these tests also
 * catch accidental float conversion that would silently lose precision.
 */

function toRawProfile(f: typeof fixtures.profile): RawCreatorProfile {
  return {
    id: BigInt(f.id),
    wallet: f.wallet,
    name: f.name,
    bio: f.bio,
    avatar_ipfs: f.avatar_ipfs,
    total_received: BigInt(f.total_received),
    tip_count: f.tip_count,
    subscriber_count: f.subscriber_count,
    registered_at: BigInt(f.registered_at),
  };
}

function toRawTip(f: typeof fixtures.tip): RawTip {
  return {
    id: BigInt(f.id),
    from: f.from,
    to: f.to,
    amount: BigInt(f.amount),
    fee_paid: BigInt(f.fee_paid),
    message_ipfs: f.message_ipfs,
    timestamp: BigInt(f.timestamp),
  };
}

function toRawSubscription(f: typeof fixtures.subscription): RawSubscription {
  return {
    id: BigInt(f.id),
    supporter: f.supporter,
    creator: f.creator,
    amount_per_month: BigInt(f.amount_per_month),
    next_charge_date: BigInt(f.next_charge_date),
    active: f.active,
    created_at: BigInt(f.created_at),
  };
}

function toRawGoal(f: typeof fixtures.tipGoal): RawTipGoal {
  return {
    id: BigInt(f.id),
    creator: f.creator,
    goal_amount: BigInt(f.goal_amount),
    current_amount: BigInt(f.current_amount),
    description: f.description,
    completed: f.completed,
    created_at: BigInt(f.created_at),
  };
}

function toRawStats(f: typeof fixtures.protocolStats): RawProtocolStats {
  return {
    total_tips: f.total_tips,
    total_volume: BigInt(f.total_volume),
    total_creators: f.total_creators,
    total_subscriptions: f.total_subscriptions,
    fee_collected: BigInt(f.fee_collected),
  };
}

function toRawLeaderboardEntry(f: typeof fixtures.leaderboardEntry): RawLeaderboardEntry {
  return {
    wallet: f.wallet,
    name: f.name,
    total_received: BigInt(f.total_received),
    tip_count: f.tip_count,
  };
}

describe("mapProfile against a real contract fixture", () => {
  const mapped = mapProfile(toRawProfile(fixtures.profile));

  it("preserves field names across the snake_case -> camelCase boundary", () => {
    expect(mapped.wallet).toBe(fixtures.profile.wallet);
    expect(mapped.avatarIpfs).toBe(fixtures.profile.avatar_ipfs);
  });

  it("preserves full i128 precision beyond Number.MAX_SAFE_INTEGER", () => {
    expect(fixtures.profile.total_received).toBe("120370369287037037");
    expect(mapped.totalReceived).toBe("120370369287037037");
  });

  it("converts the Unix-seconds timestamp to the correct UTC instant", () => {
    expect(fixtures.profile.registered_at).toBe(1_700_000_000);
    expect(mapped.registeredAt.toISOString()).toBe("2023-11-14T22:13:20.000Z");
  });
});

describe("mapTip against a real contract fixture", () => {
  const mapped = mapTip(toRawTip(fixtures.tip));

  it("preserves full i128 precision for amount and feePaid", () => {
    expect(mapped.amount).toBe("123456789012345678");
    expect(mapped.feePaid).toBe("3086419725308641");
  });

  it("does not swap the from/to fields", () => {
    expect(mapped.from).toBe(fixtures.tip.from);
    expect(mapped.to).toBe(fixtures.tip.to);
    expect(mapped.from).not.toBe(mapped.to);
  });

  it("converts the timestamp to the correct UTC instant", () => {
    expect(mapped.timestamp.toISOString()).toBe("2023-11-14T22:13:20.000Z");
  });
});

describe("mapSubscription against a real contract fixture", () => {
  const mapped = mapSubscription(toRawSubscription(fixtures.subscription));

  it("preserves full i128 precision for amountPerMonth", () => {
    expect(mapped.amountPerMonth).toBe("50000000000000000");
  });

  it("converts nextChargeDate (set 30 days after createdAt by the contract) correctly", () => {
    expect(fixtures.subscription.next_charge_date).toBe(1_702_592_000);
    expect(mapped.nextChargeDate.toISOString()).toBe("2023-12-14T22:13:20.000Z");
    expect(mapped.createdAt.toISOString()).toBe("2023-11-14T22:13:20.000Z");
  });

  it("preserves the active flag", () => {
    expect(mapped.active).toBe(true);
  });
});

describe("mapGoal against a real contract fixture", () => {
  const mapped = mapGoal(toRawGoal(fixtures.tipGoal));

  it("preserves full i128 precision for goalAmount and currentAmount", () => {
    expect(mapped.goalAmount).toBe("481481477148148148");
    expect(mapped.currentAmount).toBe("120370369287037037");
  });

  it("computes progressPercent from real contract-reported amounts", () => {
    // current_amount is exactly 1/4 of goal_amount in this fixture (by
    // construction in the Rust test): 120370369287037037 * 4 ==
    // 481481477148148148, so progress is exactly 25%, not an artifact of
    // float rounding.
    expect(mapped.progressPercent).toBe(25);
  });

  it("reflects the real completed flag", () => {
    expect(mapped.completed).toBe(false);
  });
});

describe("mapStats against a real contract fixture", () => {
  const mapped = mapStats(toRawStats(fixtures.protocolStats));

  it("preserves full i128 precision for totalVolume and feeCollected", () => {
    expect(mapped.totalVolume).toBe("123456789012345678");
    expect(mapped.feeCollected).toBe("3086419725308641");
  });
});

describe("mapLeaderboardEntry against a real contract fixture", () => {
  const mapped = mapLeaderboardEntry(toRawLeaderboardEntry(fixtures.leaderboardEntry));

  it("preserves full i128 precision for totalReceived", () => {
    expect(mapped.totalReceived).toBe("120370369287037037");
  });

  it("preserves field names", () => {
    expect(mapped.wallet).toBe(fixtures.leaderboardEntry.wallet);
    expect(mapped.name).toBe(fixtures.leaderboardEntry.name);
  });
});
